block_state_id mc_26_3_acacia_slab_get_state(
	const mc_26_3_acacia_slab_properties *properties
)
{
	if (properties == NULL) return BLOCK_INVALID_ID;
	if ((u32)properties->type >= 3) return BLOCK_INVALID_ID;
	if (properties->waterlogged > 1) return BLOCK_INVALID_ID;
	u32 index = ((((0) * 3 + properties->type)) * 2 + properties->waterlogged);
	return mc_26_3_acacia_slab_state_table[index];
}

b8 mc_26_3_acacia_slab_get_properties(
	block_state_id state,
	mc_26_3_acacia_slab_properties *properties
)
{
	if (properties == NULL) return 0;
	if (state < 15201 || state >= 15207) return 0;
	*properties = mc_26_3_acacia_slab_properties_by_state[state - 15201];
	return 1;
}

