block_state_id mc_26_3_cherry_shelf_get_state(
	const mc_26_3_cherry_shelf_properties *properties
)
{
	if (properties == NULL) return BLOCK_INVALID_ID;
	if ((u32)properties->facing >= 4) return BLOCK_INVALID_ID;
	if (properties->powered > 1) return BLOCK_INVALID_ID;
	if ((u32)properties->side_chain >= 4) return BLOCK_INVALID_ID;
	if (properties->waterlogged > 1) return BLOCK_INVALID_ID;
	u32 index = ((((((((0) * 4 + properties->facing)) * 2 + properties->powered)) * 4 + properties->side_chain)) * 2 + properties->waterlogged);
	return mc_26_3_cherry_shelf_state_table[index];
}

b8 mc_26_3_cherry_shelf_get_properties(
	block_state_id state,
	mc_26_3_cherry_shelf_properties *properties
)
{
	if (properties == NULL) return 0;
	if (state < 4284 || state >= 4348) return 0;
	*properties = mc_26_3_cherry_shelf_properties_by_state[state - 4284];
	return 1;
}

