block_state_id mc_26_3_deepslate_brick_stairs_get_state(
	const mc_26_3_deepslate_brick_stairs_properties *properties
)
{
	if (properties == NULL) return BLOCK_INVALID_ID;
	if ((u32)properties->facing >= 4) return BLOCK_INVALID_ID;
	if ((u32)properties->half >= 2) return BLOCK_INVALID_ID;
	if ((u32)properties->shape >= 5) return BLOCK_INVALID_ID;
	if (properties->waterlogged > 1) return BLOCK_INVALID_ID;
	u32 index = ((((((((0) * 4 + properties->facing)) * 2 + properties->half)) * 5 + properties->shape)) * 2 + properties->waterlogged);
	return mc_26_3_deepslate_brick_stairs_state_table[index];
}

b8 mc_26_3_deepslate_brick_stairs_get_properties(
	block_state_id state,
	mc_26_3_deepslate_brick_stairs_properties *properties
)
{
	if (properties == NULL) return 0;
	if (state < 35010 || state >= 35090) return 0;
	*properties = mc_26_3_deepslate_brick_stairs_properties_by_state[state - 35010];
	return 1;
}

