block_state_id mc_26_3_fire_get_state(
	const mc_26_3_fire_properties *properties
)
{
	if (properties == NULL) return BLOCK_INVALID_ID;
	if ((u32)properties->age >= 16) return BLOCK_INVALID_ID;
	if (properties->east > 1) return BLOCK_INVALID_ID;
	if (properties->north > 1) return BLOCK_INVALID_ID;
	if (properties->south > 1) return BLOCK_INVALID_ID;
	if (properties->up > 1) return BLOCK_INVALID_ID;
	if (properties->west > 1) return BLOCK_INVALID_ID;
	u32 index = ((((((((((((0) * 16 + properties->age)) * 2 + properties->east)) * 2 + properties->north)) * 2 + properties->south)) * 2 + properties->up)) * 2 + properties->west);
	return mc_26_3_fire_state_table[index];
}

b8 mc_26_3_fire_get_properties(
	block_state_id state,
	mc_26_3_fire_properties *properties
)
{
	if (properties == NULL) return 0;
	if (state < 4931 || state >= 5443) return 0;
	*properties = mc_26_3_fire_properties_by_state[state - 4931];
	return 1;
}

