block_state_id mc_26_3_mangrove_button_get_state(
	const mc_26_3_mangrove_button_properties *properties
)
{
	if (properties == NULL) return BLOCK_INVALID_ID;
	if ((u32)properties->face >= 3) return BLOCK_INVALID_ID;
	if ((u32)properties->facing >= 4) return BLOCK_INVALID_ID;
	if (properties->powered > 1) return BLOCK_INVALID_ID;
	u32 index = ((((((0) * 3 + properties->face)) * 4 + properties->facing)) * 2 + properties->powered);
	return mc_26_3_mangrove_button_state_table[index];
}

b8 mc_26_3_mangrove_button_get_properties(
	block_state_id state,
	mc_26_3_mangrove_button_properties *properties
)
{
	if (properties == NULL) return 0;
	if (state < 12610 || state >= 12634) return 0;
	*properties = mc_26_3_mangrove_button_properties_by_state[state - 12610];
	return 1;
}

