block_state_id mc_26_3_pale_moss_carpet_get_state(
	const mc_26_3_pale_moss_carpet_properties *properties
)
{
	if (properties == NULL) return BLOCK_INVALID_ID;
	if (properties->bottom > 1) return BLOCK_INVALID_ID;
	if ((u32)properties->east >= 3) return BLOCK_INVALID_ID;
	if ((u32)properties->north >= 3) return BLOCK_INVALID_ID;
	if ((u32)properties->south >= 3) return BLOCK_INVALID_ID;
	if ((u32)properties->west >= 3) return BLOCK_INVALID_ID;
	u32 index = ((((((((((0) * 2 + properties->bottom)) * 3 + properties->east)) * 3 + properties->north)) * 3 + properties->south)) * 3 + properties->west);
	return mc_26_3_pale_moss_carpet_state_table[index];
}

b8 mc_26_3_pale_moss_carpet_get_properties(
	block_state_id state,
	mc_26_3_pale_moss_carpet_properties *properties
)
{
	if (properties == NULL) return 0;
	if (state < 35554 || state >= 35716) return 0;
	*properties = mc_26_3_pale_moss_carpet_properties_by_state[state - 35554];
	return 1;
}

