block_state_id mc_26_3_redstone_wire_get_state(
	const mc_26_3_redstone_wire_properties *properties
)
{
	if (properties == NULL) return BLOCK_INVALID_ID;
	if ((u32)properties->east >= 3) return BLOCK_INVALID_ID;
	if ((u32)properties->north >= 3) return BLOCK_INVALID_ID;
	if ((u32)properties->power >= 16) return BLOCK_INVALID_ID;
	if ((u32)properties->south >= 3) return BLOCK_INVALID_ID;
	if ((u32)properties->west >= 3) return BLOCK_INVALID_ID;
	u32 index = ((((((((((0) * 3 + properties->east)) * 3 + properties->north)) * 16 + properties->power)) * 3 + properties->south)) * 3 + properties->west);
	return mc_26_3_redstone_wire_state_table[index];
}

b8 mc_26_3_redstone_wire_get_properties(
	block_state_id state,
	mc_26_3_redstone_wire_properties *properties
)
{
	if (properties == NULL) return 0;
	if (state < 5567 || state >= 6863) return 0;
	*properties = mc_26_3_redstone_wire_properties_by_state[state - 5567];
	return 1;
}

