block_state_id mc_26_3_sulfur_brick_wall_get_state(
	const mc_26_3_sulfur_brick_wall_properties *properties
)
{
	if (properties == NULL) return BLOCK_INVALID_ID;
	if ((u32)properties->east >= 3) return BLOCK_INVALID_ID;
	if ((u32)properties->north >= 3) return BLOCK_INVALID_ID;
	if ((u32)properties->south >= 3) return BLOCK_INVALID_ID;
	if (properties->up > 1) return BLOCK_INVALID_ID;
	if (properties->waterlogged > 1) return BLOCK_INVALID_ID;
	if ((u32)properties->west >= 3) return BLOCK_INVALID_ID;
	u32 index = ((((((((((((0) * 3 + properties->east)) * 3 + properties->north)) * 3 + properties->south)) * 2 + properties->up)) * 2 + properties->waterlogged)) * 3 + properties->west);
	return mc_26_3_sulfur_brick_wall_state_table[index];
}

