block_state_id mc_26_3_trial_spawner_get_state(
	const mc_26_3_trial_spawner_properties *properties
)
{
	if (properties == NULL) return BLOCK_INVALID_ID;
	if (properties->ominous > 1) return BLOCK_INVALID_ID;
	if ((u32)properties->trial_spawner_state >= 6) return BLOCK_INVALID_ID;
	u32 index = ((((0) * 2 + properties->ominous)) * 6 + properties->trial_spawner_state);
	return mc_26_3_trial_spawner_state_table[index];
}

b8 mc_26_3_trial_spawner_get_properties(
	block_state_id state,
	mc_26_3_trial_spawner_properties *properties
)
{
	if (properties == NULL) return 0;
	if (state < 35507 || state >= 35519) return 0;
	*properties = mc_26_3_trial_spawner_properties_by_state[state - 35507];
	return 1;
}

