block_state_id mc_26_3_waxed_copper_chest_get_state(
	const mc_26_3_waxed_copper_chest_properties *properties
)
{
	if (properties == NULL) return BLOCK_INVALID_ID;
	if ((u32)properties->type >= 3) return BLOCK_INVALID_ID;
	if ((u32)properties->facing >= 4) return BLOCK_INVALID_ID;
	if (properties->waterlogged > 1) return BLOCK_INVALID_ID;
	u32 index = ((((((0) * 3 + properties->type)) * 4 + properties->facing)) * 2 + properties->waterlogged);
	return mc_26_3_waxed_copper_chest_state_table[index];
}

b8 mc_26_3_waxed_copper_chest_get_properties(
	block_state_id state,
	mc_26_3_waxed_copper_chest_properties *properties
)
{
	if (properties == NULL) return 0;
	if (state < 33021 || state >= 33045) return 0;
	*properties = mc_26_3_waxed_copper_chest_properties_by_state[state - 33021];
	return 1;
}

