block_state_id mc_26_3_waxed_oxidized_copper_door_get_state(
	const mc_26_3_waxed_oxidized_copper_door_properties *properties
)
{
	if (properties == NULL) return BLOCK_INVALID_ID;
	if ((u32)properties->facing >= 4) return BLOCK_INVALID_ID;
	if ((u32)properties->half >= 2) return BLOCK_INVALID_ID;
	if ((u32)properties->hinge >= 2) return BLOCK_INVALID_ID;
	if (properties->open > 1) return BLOCK_INVALID_ID;
	if (properties->powered > 1) return BLOCK_INVALID_ID;
	u32 index = ((((((((((0) * 4 + properties->facing)) * 2 + properties->half)) * 2 + properties->hinge)) * 2 + properties->open)) * 2 + properties->powered);
	return mc_26_3_waxed_oxidized_copper_door_state_table[index];
}

b8 mc_26_3_waxed_oxidized_copper_door_get_properties(
	block_state_id state,
	mc_26_3_waxed_oxidized_copper_door_properties *properties
)
{
	if (properties == NULL) return 0;
	if (state < 32301 || state >= 32365) return 0;
	*properties = mc_26_3_waxed_oxidized_copper_door_properties_by_state[state - 32301];
	return 1;
}

